    // com a aba Compras / Analytics / Fornecedores).
    const bookingsPaid = sumQuantity((bookings || []).filter(b => b.status === 'pago'));
    const giftCardsActive = (giftCardsResult.rows || []).filter(
      g => g.status === 'active' || g.status === 'used'
    ).length;
